const formatEventDateRange = (startDate, endDate) => {
  const options = { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' };
  const start = new Date(`${startDate}T00:00:00Z`);
  const end = new Date(`${endDate}T00:00:00Z`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime())) return '';
  if (startDate === endDate) return new Intl.DateTimeFormat('en-CA', options).format(start);
  const sameMonth = start.getUTCFullYear() === end.getUTCFullYear() && start.getUTCMonth() === end.getUTCMonth();
  if (sameMonth) return `${new Intl.DateTimeFormat('en-CA', { month: 'short', timeZone: 'UTC' }).format(start)} ${start.getUTCDate()}–${end.getUTCDate()}, ${end.getUTCFullYear()}`;
  return `${new Intl.DateTimeFormat('en-CA', { month: 'short', day: 'numeric', timeZone: 'UTC' }).format(start)}–${new Intl.DateTimeFormat('en-CA', options).format(end)}`;
};
