function sanitizeRichHtml(value = '') {
  const parser = new DOMParser();
  const doc = parser.parseFromString(`<body>${value}</body>`, 'text/html');
  const allowedTags = new Set(['P', 'BR', 'STRONG', 'B', 'EM', 'I', 'UL', 'OL', 'LI', 'A']);
  const safeProtocols = new Set(['http:', 'https:', 'mailto:']);
  const clean = (node) => {
    for (const child of [...node.children]) {
      if (!allowedTags.has(child.tagName)) {
        child.replaceWith(...child.childNodes);
        continue;
      }
      const rawHref = child.tagName === 'A' ? child.getAttribute('href') : null;
      for (const attribute of [...child.attributes]) child.removeAttribute(attribute.name);
      if (child.tagName === 'A') {
        if (rawHref) {
          try {
            const url = new URL(rawHref, location.origin);
            if (safeProtocols.has(url.protocol)) {
              child.setAttribute('href', url.href);
              child.setAttribute('rel', 'noopener noreferrer');
              if (url.origin !== location.origin) child.setAttribute('target', '_blank');
            }
          } catch { /* Drop invalid links. */ }
        }
      }
      clean(child);
    }
  };
  clean(doc.body);
  return doc.body.innerHTML;
}

