function mergeState(defaults, stored) {
  if (Array.isArray(defaults)) return Array.isArray(stored) ? stored : deepClone(defaults);
  if (defaults && typeof defaults === 'object') {
    const source = stored && typeof stored === 'object' && !Array.isArray(stored) ? stored : {};
    return Object.fromEntries(Object.entries(defaults).map(([key, value]) => [key, mergeState(value, source[key])]));
  }
  return stored === undefined || stored === null ? defaults : stored;
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return seedState();
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.version !== CURRENT_STATE_VERSION) return seedState();
    const merged = mergeState(seedState(), parsed);
    merged.communications.body = sanitizeRichHtml(merged.communications.body || '');
    return merged;
  } catch (error) {
    console.warn('Program Cue demo state was invalid and has been reset.', error);
    return seedState();
  }
}

let state = loadState();
function save() {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    return true;
  } catch (error) {
    console.error('Unable to persist Program Cue demo state.', error);
    toast('Changes could not be saved in this browser.', 'danger');
    return false;
  }
}
function resetDemo() { state = seedState(); save(); toast('Demo data reset', 'success'); render(); }

