  const map = { command: '▦', event: '▣', submissions: '▤', review: '✦', speakers: '♙', schedule: '▦', communications: '✉', tasks: '☑', programme: '▥', integrations: '⌘', settings: '⚙', search: '⌕', plus: '＋', bell: '♢', chev: '›', calendar: '▣', warning: '△', folder: '▱', clock: '◷', spark: '✦', check: '✓', upload: '⇧', file: '▧', info: 'ⓘ', more: '•••', lock: '▣', mail: '✉', sms: '◌', push: '♢', webhook: '⌁', room: '▦', user: '♙', chart: '⌁', undo: '↶' };
