const statusClass = (value = '') => { const statusValue = value.toLowerCase(); if (statusValue.includes('overdue') || statusValue.includes('failed') || statusValue.includes('conflict') || statusValue.includes('critical')) return 'danger'; if (statusValue.includes('risk') || statusValue.includes('warning') || statusValue.includes('pending') || statusValue.includes('attention') || statusValue.includes('staged')) return 'warning'; if (statusValue.includes('track') || statusValue.includes('complete') || statusValue.includes('healthy') || statusValue.includes('success') || statusValue.includes('published') || statusValue.includes('ready')) return 'success'; if (statusValue.includes('review') || statusValue.includes('progress') || statusValue.includes('scheduled') || statusValue.includes('running') || statusValue.includes('assigned')) return 'info'; return 'neutral'; };
function status(value, extra = '') { return `<span class="status ${statusClass(value)} ${extra}">${esc(value)}</span>`; }
function progress(value, className = '') { return `<div class="progress ${className}" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(value)}"><span style="width:${pct(value)}%"></span></div>`; }
function avatar(name, small = false) { const initials = String(name).split(/\s+/).map((part) => part[0]).slice(0, 2).join(''); return `<span class="avatar ${small ? 'sm' : ''}" title="${esc(name)}" aria-label="${esc(name)}">${esc(initials)}</span>`; }
