window.addEventListener('keydown', (event) => {
  const editing = ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement?.tagName) || document.activeElement?.isContentEditable;
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); openCommand(); }
  else if (event.key === '?' && !editing) { event.preventDefault(); openKeyboardHelp(); }
  else if (event.key === 'Escape' && portal.innerHTML) closePortal();
});


function validateRubric(criteria) {
  if (!Array.isArray(criteria) || !criteria.length) throw new Error('Rubric must contain at least one criterion.');
  const total = criteria.reduce((sum, criterion) => sum + Number(criterion.weight || 0), 0);
  if (Math.abs(total - 100) > 0.0001) throw new Error(`Rubric weights must total 100; received ${total}.`);
  for (const criterion of criteria) {
    if (!criterion.id || !criterion.name) throw new Error('Every rubric criterion requires an id and name.');
    if (!Number.isFinite(Number(criterion.rating)) || criterion.rating < 0 || criterion.rating > 5) throw new Error(`Rating for ${criterion.name} must be between 0 and 5.`);
  }
}
function weightedReview(criteria) { validateRubric(criteria); const score = criteria.reduce((sum, criterion) => sum + (criterion.weight * criterion.rating) / 100, 0); return { score: Number(score.toFixed(2)), percentage: Math.round(score * 20) }; }
function overlaps(aStart, aEnd, bStart, bEnd) { return aStart < bEnd && bStart < aEnd; }
function speakerSet(value = '') { return new Set(String(value).split(',').map((speaker) => speaker.trim()).filter(Boolean)); }
function sharesSpeaker(a, b) { const aSpeakers = speakerSet(a); return [...speakerSet(b)].some((speaker) => aSpeakers.has(speaker)); }
function eventRooms() { return Array.isArray(state.event.rooms) && state.event.rooms.length ? state.event.rooms : rooms; }
function sessionDuration(session) { return Number.isFinite(session?.duration) && session.duration > 0 ? session.duration : Number.isFinite(session?.end) && Number.isFinite(session?.start) && session.end > session.start ? session.end - session.start : 60; }
function validateScheduleMove({ sessions, movingId, room, start, end, trackConflictPolicy = state.settings?.trackConflict || 'warn' }) {
  if (!Array.isArray(sessions)) throw new Error('Sessions must be an array.');
  if (!['block', 'warn', 'ignore'].includes(trackConflictPolicy)) throw new Error(`Unknown track conflict policy: ${trackConflictPolicy}.`);
  if (!room) throw new Error('A destination room is required.');
  if (!Number.isFinite(start) || !Number.isFinite(end) || start >= end) throw new Error('A valid destination time is required.');
  const moving = sessions.find((session) => session.id === movingId);
  if (!moving) throw new Error(`Unknown session: ${movingId}.`);
  const roomRecord = eventRooms().find((candidate) => candidate.id === room);
  if (!roomRecord) throw new Error(`Unknown destination room: ${room}.`);
  const scheduled = sessions.filter((session) => session.id !== movingId && Number.isFinite(session.start) && Number.isFinite(session.end));
  const roomConflict = scheduled.find((session) => session.room === room && overlaps(start, end, session.start, session.end));
  const speakerConflict = scheduled.find((session) => sharesSpeaker(session.speaker, moving.speaker) && overlaps(start, end, session.start, session.end));
  const trackConflict = moving.track ? scheduled.find((session) => session.track === moving.track && overlaps(start, end, session.start, session.end)) : null;
  const expectedAttendance = Number(moving.attendance || 0);
  if (!Number.isFinite(expectedAttendance) || expectedAttendance < 0) throw new Error('Expected attendance must be a non-negative number.');
  const capacityConflict = expectedAttendance > Number(roomRecord.capacity) ? roomRecord : null;
  const blockingTrackConflict = trackConflictPolicy === 'block' ? trackConflict : null;
  return {
    valid: !roomConflict && !speakerConflict && !capacityConflict && !blockingTrackConflict,
    roomConflict,
    speakerConflict,
    trackConflict,
    capacityConflict,
    reasons: [
      roomConflict ? `Room overlaps ${roomConflict.title}.` : 'Room available.',
      speakerConflict ? `Speaker overlaps ${speakerConflict.title}.` : 'Speaker available.',
      trackConflict ? `${trackConflictPolicy === 'block' ? 'Track overlaps' : 'Track warning:'} ${trackConflict.title}.` : 'No track conflict.',
      capacityConflict ? `Expected attendance ${expectedAttendance} exceeds room capacity ${roomRecord.capacity}.` : 'Capacity is sufficient.'
    ]
  };
}
function fieldVisible(field, answers) {
  if (field.always || !field.condition) return true;
  const actual = answers[field.condition.field];
  if (field.condition.operator === 'equals') return actual === field.condition.value;
  if (field.condition.operator === 'includes') return Array.isArray(actual) ? actual.includes(field.condition.value) : String(actual || '').includes(field.condition.value);
  return false;
}
function ensureFormDraft() {
  if (!state.form.dirty && state.form.draftVersion === state.form.publishedVersion) state.form.draftVersion += 1;
  state.form.dirty = true;
}
function validateFormDefinition() {
  const errors = [];
  const ids = new Set();
  for (const field of state.form.fields) {
    if (!field.id || ids.has(field.id)) errors.push(`Duplicate or missing field id: ${field.id || '(blank)'}.`);
    ids.add(field.id);
    if (!field.label?.trim()) errors.push('Every field requires a label.');
    if (field.limit != null && (!Number.isInteger(Number(field.limit)) || Number(field.limit) < 1)) errors.push(`${field.label} has an invalid character limit.`);
    if (field.condition && !state.form.fields.some((candidate) => candidate.id === field.condition.field)) errors.push(`${field.label} references an unknown conditional field.`);
  }
  const categories = state.form.fields.find((field) => field.id === 'category')?.options || [];
  for (const [category, team] of state.form.routing) {
    if (!categories.includes(category)) errors.push(`Routing category ${category} does not exist in Session category options.`);
    if (!String(team).trim()) errors.push(`${category} requires a review team.`);
  }
  const minSpeakers = Number(document.querySelector('[data-min-speakers]')?.value || state.form.settings.minSpeakers || 1);
  const maxSpeakers = Number(document.querySelector('[data-max-speakers]')?.value || state.form.settings.maxSpeakers || 6);
  const submissionLimit = Number(document.querySelector('[data-submission-limit]')?.value || state.form.settings.submissionLimit || 0);
  const closingDate = document.querySelector('[data-closing-date]')?.value || state.form.settings.closingDate;
  if (!Number.isInteger(minSpeakers) || minSpeakers < 1) errors.push('Minimum speakers must be at least 1.');
  if (!Number.isInteger(maxSpeakers) || maxSpeakers < minSpeakers) errors.push('Maximum speakers must be greater than or equal to minimum speakers.');
  if (!Number.isInteger(submissionLimit) || submissionLimit < 1) errors.push('Submission limit must be a positive integer.');
  if (!closingDate) errors.push('A submission closing date is required.');
  return errors;
}
