  const content=`${pageHead('Speakers','Monitor speaker profiles, assets, tasks and communications.',`${button('Send reminder','','data-send-speaker-reminder')} ${button('Invite speaker','primary','data-invite-speaker')}`)}<div class="grid grid-4 mb"><section class="card metric"><div class="label">Accepted speakers</div><div class="value">83</div></section><section class="card metric"><div class="label">Ready</div><div class="value">61</div></section><section class="card metric alert-amber"><div class="label">Missing assets</div><div class="value">17</div></section><section class="card metric alert-red"><div class="label">Overdue tasks</div><div class="value">12</div></section></div><section class="card pad"><div class="table-toolbar"><input class="field" data-speaker-query value="${esc(state.ui.speakerQuery)}" placeholder="Search speakers…" aria-label="Search speakers"><select class="select" data-speaker-readiness><option ${state.ui.speakerReadiness==='All readiness'?'selected':''}>All readiness</option><option ${state.ui.speakerReadiness==='On track'?'selected':''}>On track</option><option ${state.ui.speakerReadiness==='At risk'?'selected':''}>At risk</option></select><select class="select" data-speaker-status><option ${state.ui.speakerStatus==='All statuses'?'selected':''}>All statuses</option><option ${state.ui.speakerStatus==='Accepted'?'selected':''}>Accepted</option><option ${state.ui.speakerStatus==='Invited'?'selected':''}>Invited</option></select><button type="button" class="btn" data-speaker-saved-view>Saved views</button></div><p class="tiny subtle">Showing ${filtered.length} of ${state.speakerDirectory.length} representative speakers.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Speaker</th><th>Status</th><th>Readiness</th><th>Completion</th><th>Next blocker</th><th></th></tr></thead><tbody>${rows||'<tr><td colspan="6"><div class="empty">No speakers match these filters.</div></td></tr>'}</tbody></table></div></section>`;
