  document.querySelector('[data-speaker-status]')?.addEventListener('change',(event)=>{state.ui.speakerStatus=event.target.value;save();render()});
  document.querySelector('[data-speaker-saved-view]')?.addEventListener('click',()=>toast('Current speaker filters saved as a demo view'));
  document.querySelector('[data-send-speaker-reminder]')?.addEventListener('click',()=>modal('Prepare speaker reminder',`<p>Prepare a reminder for ${state.speakerDirectory.filter((speaker)=>speaker.readiness==='At risk').length} at-risk speakers?</p><div class="validation-item ok">✓ Recipients are limited to the current event and missing requirements.</div>`,`<button type="button" class="btn" data-close>Cancel</button><button type="button" class="btn primary" data-confirm-speaker-reminder>Prepare draft</button>`));
