  document.querySelectorAll('[data-open-speaker]').forEach((element)=>{element.onclick=()=>{const speaker=state.speakerDirectory.find((item)=>item.id===element.dataset.openSpeaker);modal(speaker?.name||'Speaker',`<div class="row-main">${avatar(speaker?.name||'Speaker')}<div><strong>${esc(speaker?.role||'')}</strong><small>${esc(speaker?.status||'')}</small></div></div><div class="grid grid-3 mt"><div class="card pad"><small class="subtle">Readiness</small><strong style="display:block">${esc(speaker?.readiness||'')}</strong></div><div class="card pad"><small class="subtle">Completion</small><strong style="display:block">${speaker?.completion||0}%</strong></div><div class="card pad"><small class="subtle">Next blocker</small><strong style="display:block">${esc(speaker?.blocker||'')}</strong></div></div>`)}});
