function openScheduleMoveModal(sessionId) {
  const session=state.schedule.sessions.find((item)=>item.id===sessionId);
  if(!session){toast('Select a scheduled session first.','warning');return}
  const duration=sessionDuration(session);
  const timeOptions=[];
  for(let start=480;start<=960-duration;start+=15) timeOptions.push(`<option value="${start}" ${start===session.start?'selected':''}>${fmtTime(start)} – ${fmtTime(start+duration)}</option>`);
  modal('Move or reassign session',`<p><strong>${esc(session.title)}</strong></p><div class="form-row"><label class="label">Room<select class="select" id="move-session-room">${eventRooms().map((room)=>`<option value="${room.id}" ${room.id===session.room?'selected':''}>${esc(room.name)} · capacity ${room.capacity}</option>`).join('')}</select></label><label class="label">Time<select class="select" id="move-session-start">${timeOptions.join('')}</select></label></div><p class="subtle">The move will be staged only after room, speaker and capacity validation.</p>`,`<button type="button" class="btn" data-close>Cancel</button><button type="button" class="btn primary" data-confirm-schedule-move="${session.id}">Validate & stage</button>`);
}
function scheduleAlternativeView(view, scheduled) {
  const sorted=[...scheduled].sort((a,b)=>a.start-b.start||a.room.localeCompare(b.room));
  const roomName=(id)=>eventRooms().find((room)=>room.id===id)?.name||id||'Unscheduled';
  const row=(session)=>`<tr><td>${fmtTime(session.start)}–${fmtTime(session.end)}</td><td><button type="button" class="btn ghost small" data-session="${session.id}">${esc(session.title)}</button></td><td>${esc(session.speaker)}</td><td>${esc(roomName(session.room))}</td><td><span class="pill">${esc(session.format)}</span></td><td>${esc(session.track||'General programme')}</td></tr>`;
  if(view==='List') return `<section class="card pad schedule-alt"><div class="card-title"><h2>List view</h2><span class="right subtle">${sorted.length} scheduled sessions</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>Session</th><th>Speaker</th><th>Room</th><th>Format</th><th>Track</th></tr></thead><tbody>${sorted.map(row).join('')}</tbody></table></div></section>`;
  if(view==='Day') return `<section class="card pad schedule-alt"><div class="card-title"><h2>Day view · May 20</h2><span class="right subtle">America/Toronto</span></div><div class="agenda-list">${sorted.map((session)=>`<button type="button" class="agenda-item" data-session="${session.id}"><strong>${fmtTime(session.start)}</strong><span><b>${esc(session.title)}</b><small>${esc(session.speaker)} · ${esc(roomName(session.room))}</small></span><span class="status info">${esc(session.format)}</span></button>`).join('')}</div></section>`;
  if(view==='Week') {
    const days=['May 20','May 21','May 22'];
    return `<section class="card pad schedule-alt"><div class="card-title"><h2>Week view</h2><span class="right subtle">May 20–22, 2025</span></div><div class="week-grid">${days.map((day)=>`<div class="week-day"><h3>${day}</h3>${state.programme.filter((session)=>session.day===day).map((session)=>`<div class="card pad"><strong>${esc(session.time)}</strong><p>${esc(session.title)}</p><small>${esc(session.room)} · ${esc(session.track)}</small></div>`).join('')||'<p class="subtle">No published sessions in the seeded sample.</p>'}</div>`).join('')}</div></section>`;
  }
  const trackFor=(session)=>session.track||({Keynote:'Leadership',Presentation:'AI & Innovation',Panel:'Event Operations',Workshop:'Experience Design',Breakout:'Experience Design'}[session.format]||'General programme');
  const tracks=[...new Set(sorted.map(trackFor))];
  return `<section class="card pad schedule-alt"><div class="card-title"><h2>Track view</h2><span class="right subtle">${tracks.length} tracks</span></div><div class="track-grid">${tracks.map((track)=>`<div class="track-column"><h3>${esc(track)}</h3>${sorted.filter((session)=>trackFor(session)===track).map((session)=>`<button type="button" class="card pad" data-session="${session.id}"><strong>${esc(session.title)}</strong><small>${fmtTime(session.start)} · ${esc(roomName(session.room))}</small></button>`).join('')}</div>`).join('')}</div></section>`;
}

function schedulePage(){
  const proposed=state.schedule.proposed;
  const scheduleView=state.ui.scheduleView||'Room';
  const formatClass=(f='')=>f.toLowerCase().replace(/[^a-z]+/g,'-');
  const configuredRooms=eventRooms();
  const roomIndex=Object.fromEntries(configuredRooms.map((r,i)=>[r.id,i]));
  const roomCount=Math.max(configuredRooms.length,1);
  const startMin=480,rowMin=60,rowHeight=70;
  const gridCells=[];
  gridCells.push(`<div class="cell header time">TIME (EDT)</div>`);
  configuredRooms.forEach(r=>gridCells.push(`<div class="cell header"><strong>${esc(r.name)}</strong><small style="display:block;color:var(--muted)">Capacity ${r.capacity}</small></div>`));
  for(let i=0;i<10;i++){gridCells.push(`<div class="cell time">${fmtTime(startMin+i*rowMin)}</div>`);configuredRooms.forEach(r=>gridCells.push(`<div class="cell schedule-drop" data-drop-room="${r.id}" data-drop-start="${startMin+i*rowMin}"></div>`))}
  const scheduled=state.schedule.sessions.filter(s=>s.room&&s.start!=null&&s.end!=null);
  const cards=scheduled.map(s=>{
    const col=(roomIndex[s.room]??0)+2;
    const top=44+((s.start-startMin)/rowMin)*rowHeight+5;
    const height=Math.max(42,((s.end-s.start)/rowMin)*rowHeight-9);
    const left=`calc(72px + (100% - 72px) / ${roomCount} * ${col-2} + 5px)`;
    const width=`calc((100% - 72px) / ${roomCount} - 10px)`;
    return `<button type="button" class="session-card ${formatClass(s.format)} ${s.conflict?'conflict':''}" aria-label="${esc(s.title)}; ${fmtTime(s.start)} to ${fmtTime(s.end)}; ${esc(s.speaker)}" style="grid-column:${col};top:${top}px;left:${left};width:${width};height:${height}px" data-session="${s.id}" draggable="true"><strong>${esc(s.title)}</strong><span>${fmtTime(s.start)} – ${fmtTime(s.end)}</span><span style="display:block">${esc(s.speaker)}</span>${s.conflict?'<span style="position:absolute;right:6px;top:5px">⚠</span>':''}</button>`;
  }).join('');
  const suggested=proposed?`<button type="button" class="session-card presentation" style="top:${44+((proposed.start-startMin)/rowMin)*rowHeight+5}px;left:calc(72px + (100% - 72px) / ${roomCount} * ${roomIndex[proposed.room]} + 5px);width:calc((100% - 72px) / ${roomCount} - 10px);height:${((proposed.end-proposed.start)/rowMin)*rowHeight-9}px;border-style:dashed" aria-label="Proposed schedule move"><strong>${esc(proposed.title)}</strong><span>${fmtTime(proposed.start)} – ${fmtTime(proposed.end)}</span><span>Proposed · ${esc(proposed.speaker)}</span></button>`:'';
  const summary=`<div><small class="subtle">Readiness score</small><strong style="font-size:21px;display:block">78% ${status('On track')}</strong></div><div><small class="subtle">Sessions scheduled</small><strong style="font-size:21px;display:block">124 / 142</strong></div><div><small class="subtle">Conflicts</small><strong style="font-size:21px;color:var(--red);display:block">1${proposed?' · staged':''}</strong></div><div><small class="subtle">Room utilisation</small><strong style="font-size:21px;display:block">68%</strong></div><div><small class="subtle">Speaker conflicts</small><strong style="font-size:21px;color:var(--red);display:block">1${proposed?' · staged':''}</strong></div><div><small class="subtle">Session format legend</small><div class="pillbar mt"><span class="pill">● Keynote</span><span class="pill">● Presentation</span><span class="pill">● Panel</span><span class="pill">● Workshop</span><span class="pill">● Breakout</span></div></div>`;
  const conflict=state.schedule.sessions.find(s=>s.id==='s10'), other=state.schedule.sessions.find(s=>s.id==='s11');
  const conflictPanel=proposed?`<div class="card-title"><h2>Conflict inspector</h2>${status('Resolution staged')}</div><p>The conflict remains open until the staged move is published.</p><div class="validation-list"><span>✓ Room 303 is free from 2:15–3:15 PM</span><span>✓ Jamie Lee is available</span><span>✓ No track conflict</span><span>✓ Capacity 150 matches 150 expected attendees</span></div><div class="mt">${button('Preview staged change','','data-preview-schedule')} ${button('Publish resolution','primary','data-publish-schedule')}</div>`:`<div class="card-title"><h2>Conflict inspector</h2>${status('High impact')}</div><div class="conflict-box"><strong>Speaker conflict · 10:00–11:00 AM</strong><p>Jamie Lee is scheduled in two sessions at the same time.</p><div class="card pad mb"><strong>${esc(conflict.title)}</strong><small class="subtle" style="display:block">Room 301A · 10:00–11:00 AM · Technology</small></div><div class="card pad"><strong>${esc(other.title)}</strong><small class="subtle" style="display:block">Room 301B · 10:00–11:00 AM · Marketing</small></div></div><div class="mt"><h3>Recommended resolution</h3><p>Move “AI in Event Ops” to Room 303 at 2:15–3:15 PM.</p><div class="validation-list"><span>✓ Room 303 is available</span><span>✓ Jamie Lee is available</span><span>✓ No track conflict</span><span>✓ Capacity OK: 150 / 150</span></div><div class="mt">${button('Apply suggestion','primary','data-apply-schedule')} ${button('Dismiss','ghost','data-dismiss-conflict')}</div></div>`;
  const changePanel=proposed?`<div class="card-title"><h2>Schedule changes</h2>${status('Pending publication')}</div><div class="pending-change"><strong>Move session</strong><p>${esc(proposed.title)}<br>10:00–11:00 AM, Room 301A → 2:15–3:15 PM, Room 303</p><div>${button('Undo move','small','data-undo-schedule')}</div></div><div class="mt">${button('Publish changes','primary','data-publish-schedule')}</div>`:`<div class="card-title"><h2>Schedule changes</h2><span class="subtle right">No staged changes</span></div><p class="subtle">Moves and edits appear here before publication.</p>`;
  const dynamicUnscheduled=state.schedule.sessions.filter((session)=>!session.room).map((session)=>`<article class="unscheduled-card" draggable="true" data-unscheduled-session="${session.id}"><span class="pill">${esc(session.format)}</span><strong style="display:block;margin:6px 0">${esc(session.title)}</strong><small>${esc(session.speaker)} · Accepted session</small></article>`).join('');
  const unscheduled=dynamicUnscheduled+unscheduledSessions.map(([title,format,speaker,cap])=>`<article class="unscheduled-card"><span class="pill">${esc(format)}</span><strong style="display:block;margin:6px 0">${esc(title)}</strong><small>${esc(speaker)} · Est. cap. ${cap}</small></article>`).join('');
  const viewControls=`<div class="tabs schedule-view-tabs">${['Room','List','Day','Week','Track'].map((view)=>`<button type="button" class="tab ${scheduleView===view?'active':''}" data-schedule-view="${view}">${view}</button>`).join('')}</div>`;
  const roomWorkspace=`<div class="schedule-layout"><div><div class="card pad mb" style="display:flex;gap:12px;align-items:center"><strong>Timezone: America/Toronto (EDT)</strong><span class="subtle">Scroll horizontally to view more rooms</span><span style="margin-left:auto">Press <kbd>M</kbd> to move / reassign</span></div><div class="schedule-board"><div class="schedule-grid" style="grid-template-columns:72px repeat(${roomCount},minmax(145px,1fr));min-width:${72+roomCount*145}px">${gridCells.join('')}${cards}${suggested}</div></div><section class="card pad mt"><div class="card-title"><h2>Unscheduled sessions (${unscheduledSessions.length+state.schedule.sessions.filter((session)=>!session.room).length})</h2><a class="right subtle" href="#admin/submissions">View accepted sessions →</a></div><div class="unscheduled">${unscheduled}</div></section></div><aside class="conflict-side"><section class="card conflict-panel">${conflictPanel}</section><section class="card pad">${changePanel}</section><section class="card pad"><div class="card-title"><h2>Keyboard shortcuts</h2></div><div class="grid grid-2 tiny"><span><kbd>M</kbd> Move</span><span><kbd>Z</kbd> Undo</span><span><kbd>C</kbd> Copy</span><span><kbd>/</kbd> Commands</span></div></section></aside></div>`;
  const workspace=scheduleView==='Room'?roomWorkspace:scheduleAlternativeView(scheduleView,scheduled);
  const content=`${pageHead('Schedule Planner','Build, optimise and publish the event schedule.',`${button('Smart suggestions','','data-smart-schedule')} ${button('Preview changes','','data-preview-schedule')} ${button('Publish changes','primary','data-publish-schedule')}`)}<div class="table-toolbar"><input class="field" type="date" value="2025-05-20"><select class="select"><option>All sessions</option></select><select class="select"><option>All tracks</option></select><select class="select"><option>All statuses</option></select><select class="select"><option>All rooms</option></select><span style="margin-left:auto"></span>${viewControls}</div><section class="schedule-summary">${summary}</section>${workspace}`;
  return adminShell(content,'schedule');
}
function bindSchedule(){
  document.querySelectorAll('[data-schedule-view]').forEach((element)=>{element.onclick=()=>{state.ui.scheduleView=element.dataset.scheduleView;save();render()}});
  const stageMove=(sessionId,room,start)=>{
    const session=state.schedule.sessions.find((item)=>item.id===sessionId);
    if(!session)return false;
    const end=Number(start)+sessionDuration(session);
    const validation=validateScheduleMove({sessions:state.schedule.sessions,movingId:sessionId,room,start:Number(start),end});
    if(!validation.valid){const problem=validation.reasons.find((reason)=>!reason.endsWith('available.')&&!reason.includes('sufficient'))||validation.reasons[0];toast(problem,'danger');return false}
    state.schedule.selectedId=sessionId;
    state.schedule.proposed={...session,room,start:Number(start),end};
    save();toast('Schedule move staged','warning',{label:'Undo',fn:()=>{state.schedule.proposed=null;save();render()}});render();return true;
  };
  document.querySelector('[data-apply-schedule]')?.addEventListener('click',()=>stageMove('s10','303',855));
  document.querySelector('[data-undo-schedule]')?.addEventListener('click',()=>{state.schedule.proposed=null;save();toast('Schedule move undone');render()});
  document.querySelectorAll('[data-publish-schedule]').forEach((element)=>{element.onclick=()=>{if(!state.schedule.proposed){toast('No schedule changes to publish','warning');return}modal('Publish schedule change',`<p>Publish one staged change and update the public programme and affected calendar invitation?</p><div class="pending-change"><strong>${esc(state.schedule.proposed.title)}</strong><p>Room 301A, 10:00 AM → ${esc(eventRooms().find((room)=>room.id===state.schedule.proposed.room)?.name||state.schedule.proposed.room)}, ${fmtTime(state.schedule.proposed.start)}</p></div>`,`<button type="button" class="btn" data-close>Cancel</button><button type="button" class="btn primary" data-confirm-schedule-publish>Publish changes</button>`)}});
  document.querySelectorAll('[data-preview-schedule]').forEach((element)=>{element.onclick=()=>modal('Schedule diff',state.schedule.proposed?`<div class="diff-line del">10:00 AM · AI in Event Ops · Room 301A</div><div class="diff-line add">${fmtTime(state.schedule.proposed.start)} · AI in Event Ops · ${esc(eventRooms().find((room)=>room.id===state.schedule.proposed.room)?.name||state.schedule.proposed.room)}</div>`:'<p>No staged changes.</p>')});
  document.querySelector('[data-smart-schedule]')?.addEventListener('click',()=>modal('Smart schedule proposals',`<div class="status ai">AI advisory</div><p>One safe move is available. Program Cue validated room, speaker, track and capacity constraints.</p><div class="validation-list"><span>✓ Room 303 free from 2:15–3:15 PM</span><span>✓ Jamie Lee available</span><span>✓ No track conflict</span><span>✓ Capacity 150 / 150</span></div><div class="mt">${button('Stage suggestion','primary','data-stage-smart-schedule')}</div>`));
  document.querySelector('[data-dismiss-conflict]')?.addEventListener('click',()=>toast('Conflict remains open','warning'));
  document.querySelectorAll('[data-session]').forEach((element)=>{
    element.onclick=()=>{state.schedule.selectedId=element.dataset.session;save();toast('Session selected. Press M to move or reassign.','info')};
    element.ondragstart=(event)=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',element.dataset.session)};
  });
  document.querySelectorAll('[data-unscheduled-session]').forEach((element)=>{element.onclick=()=>openScheduleMoveModal(element.dataset.unscheduledSession);element.ondragstart=(event)=>{event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',element.dataset.unscheduledSession)}});
  document.querySelectorAll('[data-drop-room]').forEach((cell)=>{
    cell.ondragover=(event)=>{event.preventDefault();event.dataTransfer.dropEffect='move';cell.classList.add('drop-target')};
    cell.ondragleave=()=>cell.classList.remove('drop-target');
    cell.ondrop=(event)=>{event.preventDefault();cell.classList.remove('drop-target');stageMove(event.dataTransfer.getData('text/plain'),cell.dataset.dropRoom,Number(cell.dataset.dropStart))};
  });
  if(window.__scheduleKeyHandler)window.removeEventListener('keydown',window.__scheduleKeyHandler);
  window.__scheduleKeyHandler=(event)=>{const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable;if(editing||routeInfo().page!=='schedule')return;if(event.key.toLowerCase()==='m'){event.preventDefault();openScheduleMoveModal(state.schedule.selectedId)}if(event.key.toLowerCase()==='z'&&state.schedule.proposed){event.preventDefault();state.schedule.proposed=null;save();toast('Schedule move undone');render()}};
  window.addEventListener('keydown',window.__scheduleKeyHandler);
}

