  const openPreview=(integration)=>modal(`${integration.name} dry-run preview`,`<div class="status info">No provider call will be made</div><p><strong>Direction:</strong> ${esc(integration.direction)}</p><p><strong>Scope:</strong> ${esc(integration.scope)}</p><p><strong>Mapping:</strong> ${esc(integration.mapping)}</p><p><strong>Conflict policy:</strong> ${esc(integration.policy)}</p><div class="card pad mt"><strong>Proposed operation</strong><p class="subtle">Validate the mapping contract and generate an event-scoped reconciliation preview. External execution remains unavailable until the provider credentials and production binding are configured.</p></div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" data-generate-integration-preview="${esc(integration.name)}">Generate dry-run preview</button>`);
