function bindSettings(){
  document.querySelector('[data-save-settings]')?.addEventListener('click',()=>{
    const value=(name)=>document.querySelector(`[data-setting="${name}"]`);
    const organisation=value('organisation')?.value.trim();
    if(!organisation){toast('Organisation name is required.','danger');return}
    state.settings.organisation=organisation;
    state.event.timezone=value('timezone')?.value||state.event.timezone;
    state.settings.defaultLanguage=value('defaultLanguage')?.value||'English';
    state.event.repository=value('provider')?.value||state.event.repository;
    state.settings.provider=state.event.repository;
    state.settings.publicFormAccess=value('publicFormAccess')?.value||state.settings.publicFormAccess;
    state.event.retentionMonths=Number(value('retention')?.value||state.event.retentionMonths);
    for(const key of ['magicLinks','googleOAuth','microsoftOAuth','turnstile','auditEnabled','logicalExports']) state.settings[key]=Boolean(value(key)?.checked);
    save();toast('Settings saved');render();
  });
}

