function publicProgrammePage(){
  const filters=state.ui.publicFilters;
  const query=filters.query.trim().toLowerCase();
  const visible=state.programme.filter((session)=>{
    const haystack=[session.title,session.speaker,session.description,session.track,session.format,session.room].join(' ').toLowerCase();
    return (!query||haystack.includes(query))
      && (filters.day==='All days'||session.day===filters.day)
      && (filters.track==='All tracks'||session.track===filters.track)
      && (filters.format==='All formats'||session.format===filters.format)
      && (filters.room==='All rooms'||session.room===filters.room);
  });
  const selected=state.programme.find((session)=>session.id===(state.publicSelected||'p1'))||state.programme[0];
  const rows=visible.map((session)=>`<button type="button" class="programme-row ${session.id===selected.id&&state.ui.publicDetailOpen?'active':''}" data-public-session="${session.id}" style="width:100%;text-align:left;border-top:0;border-left:0;border-right:0;background:${session.id===selected.id&&state.ui.publicDetailOpen?'#f7f7ff':'white'}"><div><strong>${esc(session.time)}</strong><small class="subtle" style="display:block">${esc(session.day||'May 20')}</small></div><div><span class="pill">${esc(session.format)}</span><h3>${esc(session.title)}</h3><div class="speaker">${esc(session.speaker)}${session.speakerRole?' · '+esc(session.speakerRole):''}</div></div><div class="room-col"><strong>${esc(session.room)}</strong><small class="subtle" style="display:block">${esc(session.building)}</small></div><div class="track-col">${esc(session.track)}</div><div>${session.saved?'<span class="status success">Saved ✓</span>':'<span class="pill">＋</span>'}</div></button>`).join('')||'<section class="card pad"><h2>No matching sessions</h2><p class="subtle">Clear a filter or broaden the search.</p></section>';
  const itinerary=state.programme.filter((session)=>session.saved).map((session)=>`<button type="button" class="itinerary-item" data-public-session="${session.id}" style="width:100%;text-align:left"><strong>${esc(session.day||'May 20')} · ${esc(session.time)}</strong><span class="pill" style="float:right">${esc(session.format)}</span><p>${esc(session.title)}</p><small>${esc(session.room)}</small></button>`).join('');
  const detail=state.ui.publicDetailOpen?`<section class="card session-detail-panel"><div class="card-title"><span class="pill">${esc(selected.format)}</span><button type="button" class="icon-btn right" data-close-detail aria-label="Close session details">×</button></div><h2>${esc(selected.title)}</h2><div class="row-main mb">${avatar((selected.speaker||'Program Cue').split(',')[0])}<div><strong>${esc((selected.speaker||'Program Cue').split(',')[0])}</strong><small>${esc(selected.speakerRole)}</small></div></div><div class="mb">${button(selected.saved?'Remove from itinerary':'Add to itinerary',selected.saved?'':'primary',`data-toggle-itinerary="${selected.id}"`)} ${button('Share','','data-share-session')}</div><h3>About this session</h3><p>${esc(selected.description)}</p><div class="divider"></div><h3>Details</h3><dl><dt class="subtle">Room</dt><dd>${esc(selected.room)}</dd><dt class="subtle">Venue</dt><dd>Metro Toronto Convention Centre</dd><dt class="subtle">Building / level</dt><dd>${esc(selected.building)}</dd><dt class="subtle">Format</dt><dd>${esc(selected.format)}</dd><dt class="subtle">Track</dt><dd>${esc(selected.track)}</dd></dl></section>`:'';
  const unique=(key,label)=>[label,...new Set(state.programme.map((session)=>session[key]).filter(Boolean))];
  const options=(values,current)=>values.map((value)=>`<option ${value===current?'selected':''}>${esc(value)}</option>`).join('');
  const embedded = location.pathname?.startsWith('/embed/');
  return `<div class="public-shell ${embedded ? 'embedded' : ''}"><header class="public-top"><a class="brand" href="#public/programme" style="color:var(--ink);padding:0"><span class="brand-mark">P</span><span>Program Cue</span></a><nav class="public-nav"><a class="active">Programme</a><a>Speakers</a><a>Venue</a><a>Practical info</a></nav><button type="button" class="btn">♡ My itinerary <span class="status info">${state.programme.filter((session)=>session.saved).length}</span></button></header><section class="hero"><span class="status info">May 20–22, 2025 · Toronto, Canada</span><h1>Future of<br>Events 2025</h1><p>▣ May 20–22, 2025 · ⌖ Metro Toronto Convention Centre, Toronto</p></section><main id="main" class="public-main"><div class="public-content"><div class="public-filters"><input class="field" data-public-query value="${esc(filters.query)}" placeholder="Search sessions, speakers, or topics" aria-label="Search sessions, speakers, or topics" style="flex:1"><select class="select" data-public-filter="day">${options(unique('day','All days'),filters.day)}</select><select class="select" data-public-filter="track">${options(unique('track','All tracks'),filters.track)}</select><select class="select" data-public-filter="format">${options(unique('format','All formats'),filters.format)}</select><select class="select" data-public-filter="room">${options(unique('room','All rooms'),filters.room)}</select><button type="button" class="btn" data-clear-public>Clear filters</button></div><div class="programme-list">${rows}</div><div class="mt">${button('Load more sessions','','data-load-more')}</div></div><aside><section class="card itinerary"><div class="card-title"><h2>My itinerary</h2><span class="status info right">${state.programme.filter((session)=>session.saved).length}</span></div>${itinerary||'<p class="subtle">No saved sessions yet.</p>'}</section>${detail?`<div class="mt">${detail}</div>`:''}<section class="card pad mt"><h2>Featured speakers</h2><div class="pillbar mt">${['Alex Morgan','Taylor Lee','Jordan Kim','Morgan Patel'].map((name)=>avatar(name)).join('')}</div></section><section class="card pad mt"><h2>Venue</h2><div class="venue-photo">Metro Toronto Convention Centre</div><p>255 Front St W, Toronto, Ontario</p></section></aside></main></div>`;
}
function bindPublic(){
  document.querySelectorAll('[data-public-session]').forEach((element)=>{element.onclick=()=>{state.publicSelected=element.dataset.publicSession;state.ui.publicDetailOpen=true;save();render()}});
  document.querySelector('[data-close-detail]')?.addEventListener('click',()=>{state.ui.publicDetailOpen=false;save();render()});
  document.querySelector('[data-toggle-itinerary]')?.addEventListener('click',(event)=>{const session=state.programme.find((item)=>item.id===event.currentTarget.dataset.toggleItinerary);if(!session)return;session.saved=!session.saved;save();toast(session.saved?'Session saved to itinerary':'Session removed from itinerary');render()});
  document.querySelector('[data-share-session]')?.addEventListener('click',()=>{navigator.clipboard?.writeText(location.href);toast('Session link copied')});
  document.querySelector('[data-public-query]')?.addEventListener('input',(event)=>{state.ui.publicFilters.query=event.target.value;save();clearTimeout(bindPublic.timer);bindPublic.timer=setTimeout(render,180)});
  document.querySelectorAll('[data-public-filter]').forEach((element)=>{element.onchange=()=>{state.ui.publicFilters[element.dataset.publicFilter]=element.value;save();render()}});
  document.querySelector('[data-clear-public]')?.addEventListener('click',()=>{state.ui.publicFilters={query:'',day:'All days',track:'All tracks',format:'All formats',room:'All rooms'};save();render()});
  document.querySelector('[data-load-more]')?.addEventListener('click',()=>toast('All seeded sessions are already shown','info'));
}

function applyPage(){
  const answers={format:state.application.format,category:state.application.category};
  const draft=state.application.draft||{};
  const savedDrafts=(state.application.drafts||[]).filter((item)=>item.id!==draft.id);
  const canCreateDraft=Boolean(state.form.settings.allowMultipleDrafts);
  const draftManager=`<section class="card pad mb"><div class="card-title"><h2>Your application drafts</h2>${canCreateDraft?'<button type="button" class="btn small primary right" data-new-application-draft>New draft</button>':''}</div>${canCreateDraft?(savedDrafts.length?savedDrafts.map((item)=>`<button type="button" class="queue-card" data-open-application-draft="${item.id}" style="width:100%;text-align:left"><strong>${esc(item.title||'Untitled draft')}</strong><small class="subtle" style="display:block">${esc(item.category||state.application.category)} · ${esc(item.format||state.application.format)}</small></button>`).join(''):'<p class="subtle">No other saved drafts.</p>'):'<p class="subtle">This form allows one active draft per applicant.</p>'}</section>`;
  const inputFields=state.form.fields.filter((field)=>field.kind==='input'&&fieldVisible(field,answers));
  const fields=inputFields.map((field)=>{
    const required=field.required?'required':'';
    if(field.id==='title') return `<label class="label">${esc(field.label)} *<span class="help">${esc(field.description)}</span><input class="field" name="title" value="${esc(draft.title||'')}" ${required}></label>`;
    if(field.id==='description') return `<label class="label">${esc(field.label)} *<span class="help">${esc(field.description)}</span><textarea class="textarea" name="description" maxlength="${field.limit||1200}" ${required}>${esc(draft.description||'')}</textarea></label>`;
    if(field.id==='category') return `<label class="label">Session category *<select class="select" name="category" data-app-category ${required}>${field.options.map((option)=>`<option ${option===state.application.category?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;
    if(field.id==='format') return `<label class="label">Format *<select class="select" name="format" data-app-format ${required}>${field.options.map((option)=>`<option ${option===state.application.format?'selected':''}>${esc(option)}</option>`).join('')}</select></label>`;
    if(field.id==='materials') return `<label class="label">${esc(field.label)} *<span class="help">Required when Format is Workshop. ${esc(field.description)}</span><textarea class="textarea" name="materials" maxlength="${field.limit||500}" ${required}>${esc(draft.materials||'')}</textarea></label>`;
    if(field.type==='Multi select') return `<fieldset><legend>${esc(field.label)}${field.required?' *':''}</legend>${field.options.map((option)=>`<label><input type="checkbox" name="topics" value="${esc(option)}" ${(draft.topics||[]).includes(option)?'checked':''}> ${esc(option)}</label>`).join('<br>')}</fieldset>`;
    if(field.type==='File upload') return `<label class="label">${esc(field.label)}<span class="help">${esc(field.description)}</span><input type="file" class="field" name="files" multiple></label>`;
    return `<label class="label">${esc(field.label)}${field.required?' *':''}<span class="help">${esc(field.description)}</span><input class="field" name="${esc(field.id)}" value="${esc(draft[field.id]||'')}" ${required}></label>`;
  }).join('');
  return `<div class="public-shell"><header class="public-top"><a class="brand" href="#apply/form" style="color:var(--ink);padding:0"><span class="brand-mark">P</span><span>Program Cue</span></a>${button('Save draft','','data-save-application')}</header><main id="main" style="max-width:760px;margin:30px auto;padding:0 16px">${draftManager}<section class="card pad"><div class="card-title"><div><h1>Call for Speakers 2025</h1><p class="subtle">Future of Events 2025 · Toronto</p></div><span class="status info right">Draft</span></div><div class="stepbar mb"><span class="on"></span><span></span><span></span></div><form id="application-form" class="stack"><label class="label">Applicant email *<span class="help">A verified email is required before final submission.</span><input class="field" name="email" type="email" value="${esc(draft.email||'')}" required></label>${draft.emailVerified?'<div class="validation-item ok">✓ Email verified for evaluator demo</div>':''}<label class="label">Primary speaker *<input class="field" name="speaker" value="${esc(draft.speaker||'')}" required></label><label class="label">Additional speakers<span class="help">Comma-separated. Total speakers must remain within the form limits.</span><input class="field" name="coSpeakers" value="${esc(draft.coSpeakers||'')}" placeholder="Jamie Lee, Priya Nair"></label><label class="label">Proposal video URL<span class="help">Optional alternative or supporting video submission.</span><input class="field" name="videoUrl" type="url" value="${esc(draft.videoUrl||'')}" placeholder="https://…"></label>${fields}<div style="display:flex;gap:8px"><button class="btn" type="button" data-save-application>Save and continue later</button><button class="btn primary" type="submit" style="margin-left:auto">Submit application</button></div></form></section></main></div>`;
}
function bindApply(){
  const persistDraft=()=>{const form=document.querySelector('#application-form');if(!form)return;const data=new FormData(form);const id=state.application.activeDraftId||state.application.draft?.id||uid('draft');const category=String(data.get('category')||state.application.category||'AI & Innovation');const format=String(data.get('format')||state.application.format||'Workshop');state.application.category=category;state.application.format=format;state.application.draft={id,title:String(data.get('title')||''),description:String(data.get('description')||''),speaker:String(data.get('speaker')||''),email:String(data.get('email')||''),emailVerified:Boolean(state.application.draft?.emailVerified),coSpeakers:String(data.get('coSpeakers')||''),videoUrl:String(data.get('videoUrl')||''),materials:String(data.get('materials')||''),topics:data.getAll('topics').map(String),category,format};const index=(state.application.drafts||[]).findIndex((item)=>item.id===id);if(index>=0)state.application.drafts[index]=deepClone(state.application.draft);else state.application.drafts.push(deepClone(state.application.draft));save()};
  document.querySelector('[data-new-application-draft]')?.addEventListener('click',()=>{persistDraft();const id=uid('draft');state.application.activeDraftId=id;state.application.draft={id,title:'',description:'',speaker:state.application.draft.speaker||'Alex Morgan',email:state.application.draft.email||'',emailVerified:Boolean(state.application.draft.emailVerified),coSpeakers:'',videoUrl:'',materials:'',topics:[]};state.application.format='Workshop';state.application.category='AI & Innovation';save();render()});
  document.querySelectorAll('[data-open-application-draft]').forEach((element)=>{element.onclick=()=>{persistDraft();const selected=state.application.drafts.find((item)=>item.id===element.dataset.openApplicationDraft);if(!selected)return;state.application.activeDraftId=selected.id;state.application.draft=deepClone(selected);state.application.format=selected.format||'Workshop';state.application.category=selected.category||'AI & Innovation';save();render()}});
  document.querySelector('[data-app-format]')?.addEventListener('change',(event)=>{persistDraft();state.application.format=event.target.value;save();render()});
  document.querySelector('[data-app-category]')?.addEventListener('change',(event)=>{state.application.category=event.target.value;persistDraft()});
  document.querySelectorAll('[data-save-application]').forEach((element)=>{element.onclick=()=>{persistDraft();toast('Application draft saved')}});
  document.querySelector('#application-form')?.addEventListener('input',()=>{clearTimeout(bindApply.timer);bindApply.timer=setTimeout(persistDraft,400)});
  document.querySelector('#application-form')?.addEventListener('submit',(event)=>{
    event.preventDefault();
    const form=event.currentTarget;
    if(!form.reportValidity()) return;
    const data=new FormData(form);
    const title=String(data.get('title')||'').trim();
    const description=String(data.get('description')||'').trim();
    const speaker=String(data.get('speaker')||'').trim();
    const email=String(data.get('email')||'').trim();
    const coSpeakers=String(data.get('coSpeakers')||'').split(',').map((value)=>value.trim()).filter(Boolean);
    const speakers=[speaker,...coSpeakers];
    const minSpeakers=Number(state.form.settings.minSpeakers||1),maxSpeakers=Number(state.form.settings.maxSpeakers||6);
    if(speakers.length<minSpeakers||speakers.length>maxSpeakers){toast(`This form requires ${minSpeakers}–${maxSpeakers} speakers.`, 'danger');return}
    if(!title||!description||!speaker||!email){toast('Applicant email, primary speaker, session title and description are required.','danger');return}
    if(state.settings.publicFormAccess==='email-verified'&&!state.application.draft.emailVerified){toast('Verify the applicant email before submitting.','danger');return}
    if(state.submissions.length>=Number(state.form.settings.submissionLimit||0)){toast('This call for speakers has reached its submission limit.','danger');return}
    const id=`SUB-${2600+state.submissions.length}`;
    state.submissions.unshift({id,title,author:speaker,applicantEmail:email,category:state.application.category,format:state.application.format,track:state.application.category,status:'Submitted',reviews:0,requiredReviews:2,due:'Jun 30',abstract:description,speakers,attachments:[],videoUrl:String(data.get('videoUrl')||'').trim(),tags:['Public application']});
    state.application.drafts=(state.application.drafts||[]).filter((item)=>item.id!==state.application.activeDraftId);const nextId=uid('draft');state.application.activeDraftId=nextId;state.application.draft={id:nextId,title:'',description:'',speaker,email:String(data.get('email')||''),emailVerified:true,coSpeakers:'',videoUrl:'',materials:'',topics:[]};
    save();toast(state.form.settings.sendConfirmation?'Application submitted; confirmation email queued.':'Application submitted successfully');go('speaker/dashboard');
  });
}

function designSystemPage(){return `<main id="main" class="design-board"><div class="page-head"><div><h1>Program Cue design system</h1><p>One coherent system across administration, speakers and public programme.</p></div><a class="btn" href="#admin/command">Open product</a></div><div class="grid grid-3"><section class="card design-section"><h2>Brand and identity</h2><div class="brand" style="color:var(--ink);padding:14px 0"><span class="brand-mark">P</span><span>Program Cue</span></div><p>Indigo primary, violet AI only, semantic red/amber/green/blue.</p></section><section class="card design-section"><h2>Semantic colours</h2><div class="component-row mt">${status('Success')}${status('Warning')}${status('Conflict')}${status('Info')}<span class="status ai">AI Assist</span></div></section><section class="card design-section"><h2>Buttons</h2><div class="component-row mt">${button('Primary','primary')}${button('Secondary')}${button('Delete','danger')}</div></section><section class="card design-section"><h2>Data taxonomy</h2><h3>Format</h3><div class="pillbar"><span class="pill">Keynote</span><span class="pill">Panel</span><span class="pill">Workshop</span></div><h3 class="mt">Track</h3><div class="pillbar"><span class="pill track">AI & Innovation</span><span class="pill track">Event Operations</span></div></section><section class="card design-section"><h2>Search semantics</h2><p><strong>Global:</strong> Search or run a command · ⌘K</p><p><strong>Page:</strong> Filters current page only</p><p><strong>Public:</strong> Search sessions and speakers</p></section><section class="card design-section"><h2>Preview / Diff / Confirm</h2><div class="component-row mt"><span class="step-num">1</span> Preview <span>→</span><span class="step-num">2</span> Diff <span>→</span><span class="step-num">3</span> Confirm</div></section></div></main>`}

function assistantPage(){
  const content=`${pageHead('Program Cue Assistant','Prepare safe plans using the same permissions, validation and approval controls as the administrator UI.')}<div class="grid grid-2"><section class="card pad"><div class="card-title"><h2>Request</h2><span class="status ai">Advisory</span></div><textarea id="assistant-request" class="textarea" style="min-height:150px">Draft a conflict-free schedule proposal and prepare targeted reminders for speakers missing required assets.</textarea><div class="mt">${button('Prepare plan','primary','data-prepare-agent')}</div></section><section class="card pad"><h2>Execution contract</h2><p>✓ Read-only planning first</p><p>✓ Current user permissions enforced</p><p>✓ Affected records shown before writes</p><p>✓ Preview and diff required</p><p>✓ Explicit approval and audit record</p><p>✓ Publishing and sending remain separate actions</p></section></div><section id="agent-plan" class="card pad mt"><h2>Proposed plan</h2><p class="subtle">No records have been inspected yet. Prepare a plan to continue.</p></section>`;
  return adminShell(content,'command');
}
function bindAssistant(){
  document.querySelector('[data-prepare-agent]')?.addEventListener('click',()=>{
    document.querySelector('#agent-plan').innerHTML=`<div class="card-title"><h2>Proposed plan</h2>${status('Awaiting approval')}</div><ol><li>Stage a validated schedule move for AI in Event Ops.</li><li>Create 17 reminder drafts for speakers missing required assets.</li><li>Re-run conflict and recipient validation.</li></ol><div class="grid grid-3"><div class="card pad"><strong>18 records read</strong><p class="subtle">Authorised event data</p></div><div class="card pad"><strong>1 staged write</strong><p class="subtle">No publication</p></div><div class="card pad"><strong>17 drafts</strong><p class="subtle">No messages sent</p></div></div><div class="mt">${button('Preview diff','')} ${button('Approve & stage','primary','data-approve-agent')}</div>`;
    document.querySelector('[data-approve-agent]')?.addEventListener('click',()=>modal('Approve assistant plan',`<p>This stages one schedule move and creates 17 message drafts. It does not publish the schedule or send messages.</p><div class="status ai">All permission and validation checks passed</div>`,`<button class="btn" data-close>Cancel</button><button class="btn primary" data-confirm-agent>Approve & stage</button>`));
  });
}

function bindPortalActions() {
  bindPortalDynamic();
  document.querySelector('[data-preview-proposal]')?.addEventListener('click', () => { closePortal(); go('admin/schedule'); toast('Schedule proposal opened for review', 'info'); });
  document.querySelector('[data-confirm-admin-invite]')?.addEventListener('click',()=>{const name=document.querySelector('#invite-admin-name')?.value.trim();const email=document.querySelector('#invite-admin-email')?.value.trim();if(!name||!email||!email.includes('@')){toast('A valid administrator name and email are required.','danger');return}state.event.administrators.push({id:uid('admin'),name,email,role:'Event administrator',status:'Invited'});save();closePortal();toast('Administrator invitation queued');render()});
  document.querySelector('[data-confirm-add-room]')?.addEventListener('click',()=>{const name=document.querySelector('#new-room-name')?.value.trim();const capacity=Number(document.querySelector('#new-room-capacity')?.value);if(!name||!Number.isFinite(capacity)||capacity<1){toast('Room name and a positive capacity are required.','danger');return}const id=slug(name)||uid('room');if(eventRooms().some((room)=>room.id===id||room.name.toLowerCase()===name.toLowerCase())){toast('That room already exists.','danger');return}state.event.rooms.push({id,name,capacity});save();closePortal();toast('Room added');render()});
  document.querySelector('[data-confirm-speaker-reminder]')?.addEventListener('click',()=>{closePortal();toast('Targeted reminder draft prepared for review','info');go('admin/communications')});
  document.querySelector('[data-confirm-speaker-invite]')?.addEventListener('click',()=>{const name=document.querySelector('#invite-speaker-name')?.value.trim();const email=document.querySelector('#invite-speaker-email')?.value.trim();if(!name||!email||!email.includes('@')){toast('A valid name and email are required.','danger');return}state.speakerDirectory.push({id:uid('speaker'),name,role:'Invited speaker',status:'Invited',readiness:'At risk',completion:0,blocker:'Invitation not accepted'});save();closePortal();toast('Speaker invitation queued');render()});
  document.querySelector('[data-add-evaluation-round]')?.addEventListener('click',()=>{const number=state.review.plan.rounds.length+1;state.review.plan.rounds.push({id:uid('round'),name:`Round ${number}`,status:'Draft'});save();closePortal();toast('Evaluation round added');render()});
  document.querySelectorAll('[data-confirm-decision]').forEach((element)=>{element.onclick=()=>{const submission=state.submissions.find((item)=>item.id===element.dataset.submissionId);if(!submission){toast('Submission no longer exists.','danger');return}const accepted=element.dataset.confirmDecision==='accept';submission.status=accepted?'Accepted':'Rejected';submission.decisionFeedback=document.querySelector('#decision-feedback')?.value.trim()||'';if(accepted&&!state.schedule.sessions.some((session)=>session.sourceSubmissionId===submission.id)){state.schedule.sessions.push({id:uid('session'),sourceSubmissionId:submission.id,title:submission.title,speaker:submission.speakers.join(', '),format:submission.format,track:submission.track,room:null,start:null,end:null,duration:60,attendance:100,conflict:false})}save();closePortal();toast(accepted?'Submission accepted; session added to the unscheduled queue.':'Submission rejected; notification draft prepared.',accepted?'success':'warning');render()}});
  document.querySelector('[data-confirm-direct-session]')?.addEventListener('click', () => {
    const title = document.querySelector('#direct-session-title')?.value.trim();
    const speaker = document.querySelector('#direct-session-speaker')?.value.trim();
    if (!title || !speaker) { toast('Session title and primary speaker are required.', 'danger'); return; }
    const format = document.querySelector('#direct-session-format')?.value || 'Presentation';
    const category = document.querySelector('#direct-session-category')?.value || 'Event Operations';
    const id = `DIR-${String(state.submissions.length + 1).padStart(4, '0')}`;
    state.submissions.unshift({ id, title, author: speaker, category, format, track: category, status: 'Accepted', reviews: 0, requiredReviews: 0, due: 'Direct session', abstract: 'Direct session created by an event administrator.', speakers: [speaker], attachments: [], tags: ['Direct session'] });
    state.schedule.sessions.push({ id: uid('session'), sourceSubmissionId: id, title, speaker, format, track: category, room: null, start: null, end: null, duration: 60, attendance: 100, conflict: false });
    save(); closePortal(); toast('Direct session created and added to the unscheduled queue'); go('admin/submissions'); render();
  });
  document.querySelector('[data-confirm-schedule-move]')?.addEventListener('click', (event) => {
    const session=state.schedule.sessions.find((item)=>item.id===event.currentTarget.dataset.confirmScheduleMove);
    const room=document.querySelector('#move-session-room')?.value;
    const start=Number(document.querySelector('#move-session-start')?.value);
    if(!session||!room||!Number.isFinite(start)){toast('Choose a valid room and time.','danger');return}
    const end=start+sessionDuration(session);
    const validation=validateScheduleMove({sessions:state.schedule.sessions,movingId:session.id,room,start,end});
    if(!validation.valid){toast(validation.reasons.find((reason)=>!reason.endsWith('available.')&&!reason.includes('sufficient'))||validation.reasons[0],'danger');return}
    state.schedule.proposed={...session,room,start,end};state.schedule.selectedId=session.id;save();closePortal();toast('Schedule move staged','warning');render();
  });
  document.querySelector('[data-stage-smart-schedule]')?.addEventListener('click', () => {
    const session=state.schedule.sessions.find((item)=>item.id==='s10');
    const validation=validateScheduleMove({sessions:state.schedule.sessions,movingId:'s10',room:'303',start:855,end:915});
    if(!validation.valid){toast(validation.reasons.join(' '),'danger');return}
    state.schedule.proposed={...session,room:'303',start:855,end:915};state.schedule.selectedId='s10';save();closePortal();toast('Smart suggestion staged for review','warning');render();
  });
  document.querySelector('[data-confirm-schedule-publish]')?.addEventListener('click', () => {
    const proposal = state.schedule.proposed;
    if (!proposal) { toast('The staged schedule change no longer exists.', 'danger'); closePortal(); return; }
    const validation = validateScheduleMove({ sessions: state.schedule.sessions, movingId: proposal.id, room: proposal.room, start: proposal.start, end: proposal.end });
    if (!validation.valid) { toast(validation.reasons.find((reason) => !reason.includes('available') && !reason.includes('sufficient')) || 'The proposed schedule move is no longer valid.', 'danger'); closePortal(); render(); return; }
    const session = state.schedule.sessions.find((item) => item.id === proposal.id);
    Object.assign(session, { room: proposal.room, start: proposal.start, end: proposal.end, conflict: false });
    const pairedConflict = state.schedule.sessions.find((item) => item.id === 's11');
    if (pairedConflict) pairedConflict.conflict = false;
    state.schedule.proposed = null;
    state.schedule.publishedAt = new Date().toISOString();
    save(); closePortal(); toast('Schedule version published'); render();
  });
  document.querySelector('[data-add-task]')?.addEventListener('click', () => {
    const name = document.querySelector('#new-task-name')?.value.trim();
    const impact = document.querySelector('#new-task-impact')?.value || 'Medium';
    const entityType = document.querySelector('#new-task-entity')?.value || 'Speaker';
    if (!name) { toast('Task name is required', 'danger'); return; }
    state.tasks.push({ id: uid('task'), entityType, task: name, context: `New ${entityType.toLowerCase()} task`, owner: 'Event Ops', due: 'May 30, 2025', dueNote: '10 days', status: 'Not started', impact, readiness: 0, evidence: null });
    save(); closePortal(); toast('Task created'); render();
  });
  document.querySelectorAll('[data-apply-task-template]').forEach((element)=>{element.onclick=()=>{const kind=element.dataset.applyTaskTemplate;const definitions=kind==='speaker'?[['Approve public biography','Speaker','High'],['Upload presentation slides','Speaker','High'],['Confirm A/V requirements','Speaker','Medium']]:[['Confirm run of show','Session','High'],['Review accessibility requirements','Session','High'],['Confirm room setup','Session','Medium']];for(const [title,entityType,impact] of definitions){state.tasks.push({id:uid('task'),entityType,task:title,context:`${kind==='speaker'?'Speaker onboarding':'Session readiness'} template`,owner:'Event Ops',due:'May 30, 2025',dueNote:'10 days',status:'Not started',impact,readiness:0,evidence:null})}save();closePortal();toast(`${definitions.length} tasks created from template`);render()}});
  document.querySelectorAll('[data-complete-task]').forEach((element) => { element.onclick = () => {
    const task = state.tasks.find((item) => item.id === element.dataset.completeTask);
    if (!task) return;
    const previous = { status: task.status, readiness: task.readiness };
    task.status = 'Completed'; task.readiness = 100; save(); closePortal();
    toast('Task completed', 'success', { label: 'Undo', fn: () => { task.status = previous.status; task.readiness = previous.readiness; save(); render(); } });
    render();
  }; });
  document.querySelector('[data-confirm-programme]')?.addEventListener('click', () => { state.programmePublishedAt = new Date().toISOString(); save(); closePortal(); toast('Programme version 9 published'); });
  document.querySelector('[data-confirm-agent]')?.addEventListener('click', () => {
    if (!state.schedule.proposed) {
      const moving = state.schedule.sessions.find((item) => item.id === 's10');
      const validation = validateScheduleMove({ sessions: state.schedule.sessions, movingId: moving.id, room: '303', start: 855, end: 915 });
      if (validation.valid) state.schedule.proposed = { ...moving, room: '303', start: 855, end: 915, attendance: moving.attendance };
    }
    state.agentDrafts = 17;
    save(); closePortal(); toast('Assistant plan approved and staged'); render();
  });
  document.querySelector('[data-save-programme-branding]')?.addEventListener('click',()=>{state.programmeSettings.accent=document.querySelector('#programme-accent')?.value||state.programmeSettings.accent;state.programmeSettings.heroStyle=document.querySelector('#programme-hero')?.value||state.programmeSettings.heroStyle;save();closePortal();toast('Programme branding saved');render()});
  document.querySelector('[data-save-itinerary-settings]')?.addEventListener('click',()=>{state.programmeSettings.anonymousItinerary=Boolean(document.querySelector('#anonymous-itinerary')?.checked);state.programmeSettings.conflictWarnings=Boolean(document.querySelector('#itinerary-conflicts')?.checked);state.programmeSettings.publicSearch=Boolean(document.querySelector('#public-search')?.checked);save();closePortal();toast('Itinerary settings saved');render()});
  document.querySelector('[data-final-send]')?.addEventListener('click', () => {
    if (!state.communications.footerValid) { toast('Resolve the critical validation blocker before sending.', 'danger'); return; }
    state.communications.sent.push({ at: new Date().toISOString(), recipients: 26541, status: 'queued' });
    save(); closePortal(); toast('Communication queued for delivery'); render();
  });
  document.querySelector('[data-save-av]')?.addEventListener('click', () => {
    state.speaker.avConfirmed = Boolean(document.querySelector('#speaker-av-confirmed')?.checked);
    save(); closePortal(); toast(state.speaker.avConfirmed ? 'A/V requirements confirmed' : 'A/V confirmation removed', state.speaker.avConfirmed ? 'success' : 'warning'); render();
  });
  document.querySelectorAll('[data-generate-integration-preview]').forEach((element)=>{element.onclick=()=>{const provider=element.dataset.generateIntegrationPreview;const integration=state.integrations.find((item)=>item.name===provider);if(integration){integration.activity=`Dry-run preview generated · ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`;save()}closePortal();toast(`${provider} dry-run preview generated; no provider call was made.`,'info');render()}});
  document.querySelectorAll('[data-connect-provider]').forEach((element)=>{element.onclick=()=>{const provider=element.dataset.connectProvider;closePortal();toast(`${provider} requires production credentials before it can be connected.`,'warning')}});
  document.querySelector('[data-confirm-speaker-profile]')?.addEventListener('click', () => {
    const shortBio = document.querySelector('#speaker-short-bio')?.value.trim() || '';
    const bio = document.querySelector('#speaker-bio')?.value.trim() || '';
    const socialUrl = document.querySelector('#speaker-social')?.value.trim() || '';
    if (!shortBio || !bio) { toast('Short and full biographies are required.', 'danger'); return; }
    if (socialUrl) { try { new URL(socialUrl); } catch { toast('Public profile URL must be valid.', 'danger'); return; } }
    state.speaker.shortBio = shortBio;
    state.speaker.bio = bio;
    state.speaker.pronunciation = document.querySelector('#speaker-pronunciation')?.value.trim() || '';
    state.speaker.socialUrl = socialUrl;
    state.speaker.profilePublished = Boolean(document.querySelector('#speaker-publish-profile')?.checked);
    state.speaker.profileComplete = true;
    save(); closePortal(); toast(state.speaker.profilePublished ? 'Profile saved and published' : 'Profile saved'); render();
  });
  document.querySelector('[data-confirm-speaker-asset]')?.addEventListener('click', () => {
    const file = document.querySelector('#speaker-asset-file')?.files?.[0];
    const kind = document.querySelector('#speaker-asset-kind')?.value || 'Session asset';
    if (!file) { toast('Choose a file before uploading.', 'danger'); return; }
    if (!/\.(pdf|ppt|pptx|png|jpe?g|zip)$/i.test(file.name)) { toast('Use PDF, PPTX, PNG, JPG or ZIP.', 'danger'); return; }
    if (file.size > 25 * 1024 * 1024) { toast('The file exceeds the 25 MB limit.', 'danger'); return; }
    state.speaker.assets.push({ id: uid('asset'), kind, name: file.name, size: file.size, uploadedAt: new Date().toISOString() });
    save(); closePortal(); toast(`${kind} uploaded and versioned`); render();
  });
  document.querySelector('[data-confirm-speaker-upload]')?.addEventListener('click', () => {
    const file = document.querySelector('#speaker-file')?.files?.[0];
    if (!file) { toast('Choose a PPTX or PDF file before uploading.', 'danger'); return; }
    const allowed = new Set(['application/pdf', 'application/vnd.ms-powerpoint', 'application/vnd.openxmlformats-officedocument.presentationml.presentation']);
    const extensionAllowed = /\.(pdf|ppt|pptx)$/i.test(file.name);
    if (!allowed.has(file.type) && !extensionAllowed) { toast('Only PDF, PPT and PPTX files are accepted.', 'danger'); return; }
    if (file.size > 100 * 1024 * 1024) { toast('The file exceeds the 100 MB limit.', 'danger'); return; }
    state.speaker.slidesUploaded = true;
    state.speaker.slideFilename = file.name;
    save(); closePortal(); toast('Slides uploaded and versioned'); render();
  });
}

function render(){
  const {scope,page,id}=routeInfo();
  let html,bind=()=>{};
  if(scope==='speaker'){if(page==='resources'){html=speakerResourcesPage();bind=bindSpeakerResources}else{html=speakerDashboardPage();bind=bindSpeaker}}
  else if(scope==='public'){html=publicProgrammePage();bind=bindPublic}
  else if(scope==='apply'){html=applyPage();bind=bindApply}
  else if(scope==='design'){html=designSystemPage()}
  else {
    const routes={
      command:[commandPage,bindCommand],event:[eventPage,bindEvent],submissions:id==='form'?[formBuilderPage,bindForm]:[submissionsPage,bindSubmissions],review:[reviewPage,bindReview],speakers:[speakersPage,bindSpeakers],schedule:[schedulePage,bindSchedule],communications:[communicationsPage,bindCommunications],tasks:[tasksPage,bindTasks],programme:[programmeAdminPage,bindProgrammeAdmin],integrations:[integrationsPage,bindIntegrations],settings:[settingsPage,bindSettings],assistant:[assistantPage,bindAssistant]
    };
    const pair=routes[page]||routes.command;html=pair[0]();bind=pair[1];
  }
  app.innerHTML=html;bindGlobal();bind();bindPortalActions();document.title=`Program Cue · ${scope==='admin'?page:scope}`;
}

render();
